using System;

namespace StdbModule;

public static partial class PolishQuotes
{
    public static class StanisławIgnacyWitkiewicz
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Boję się przyjaciół na równi z samotnością. Boję się życia i boję się śmierci.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Głębia ziewa na powierzchni, a powierzchnia okazuje się dnem głębi.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Ja muszę żyć wszystkim, co mam dane, jeżeli kiedy będę jednolitym, to znaczy, że trzymam w ręku wszystkie rozpryskujące się ogniska, z których się składam.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Jestem sam i nie wiem, czy zdobędę tę pustkę, która wszystko rodzi. Splugawiona jest moja głębia. Zabiłem w sobie głębię, to, co mogło być piękne, żebym nie chciał tworzyć życia z kobietą wolną. Ach, czemu kobieta chce być niewolnicą!", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Mnie trzeba strasznie, bez pamięci kochać i trzymać z całej siły. Inaczej nie ma mnie. Ginę czasem nawet sama dla siebie. Sama siebie nie znam w takich chwilach.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Nieustraszony, z kopią w dłoni i odbiciem jedności w sercu, zdobyłem jej wieżę i wyniosłem ją na białe anemonem pole, i w cieniu olbrzymiego lasu pierwszym zbudziłem pocałunkiem.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Prawdziwa kobieta nie jest zła ani dobra, jest kobietą – to wystarcza, a winni są zawsze tylko i jedynie mężczyźni.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Wczoraj na przykład zdradziłem jedną kobietę z następną tylko dla samego faktu zdradzenia, żeby zobaczyć, jak to wygląda, i żeby nauczyć się trochę kłamać. Przekonałem się, że kłamstwo jest absolutnie koniecznym i że trzeba go się uczyć tak jak matematyki albo geologii. Bez tego żyć nie można.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Xylotet zapłakał bawolimi łzami i stał się chytrym jak gwiaździste niebo i ponurym jak parawan w trzeciorzędnym burdelu.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Ból fizyczny i teoretyczna rozmowa są moimi jedynymi przyjemnościami – wtedy nie myślę o rzeczywistości mego życia…", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Dwa są tylko miejsca dla metafizycznych jednostek w naszych czasach: więzienie i szpital wariatów.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Jestem skończona, pragmatyczna, świadoma siebie hiperkanalia. Dlatego stoję przed wami, że wiem, co jest istotą Istnienia: metafizyczne świństwo.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Och! Co za szczęście! Co za rozkosz! Nie wiedzieć, kim się jest – być wszystkim!!!", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "W piekle nie ma żadnych mąk. Tam tylko czekają. Piekło jest jedną wielką poczekalnią.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Ja nie mam siły nawet na samobójstwo, a umęczony jestem samym sobą aż do zdechnięcia. I mimo to czuję się młodzieńcem, który może się nawet zakochać.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Mam takie uczucie, jak dziewica gwałcona przez batalion rozbestwionych żołnierzy, jak chrabąszcz, któremu by dawano końską lewatywę.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Wyrżnąć wszystkich. Nie chcę nikogo – chcę być zupełnie sam.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Blask Tajemnicy Wiekuistej wyrżnął Izydora prosto w pysk, jak świetlisty bufor jakiegoś załadowanego potwornością całego Istnienia mgławicowego monstre-pociągu.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Literatura – gówienko małe ludzkości wobec filozofii.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Zupa pomidorowa zaprawiona była zabójczym jadem prawdziwego małżeńskiego szczęścia. Tak dobrze było, że aż płakać się wprost chciało, wyć, jak wyje tylko pies na łańcuchu.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Chcę mieć cyjanek potasu, dlatego, żeby w każdej chwili być panem swego życia. Gdybym kończył, to nie chcę się strzelać, bo to niepewne i można chybić, i być odratowanym.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Uwiodłem portugalską kurwę z Brazylii, ale bez wielkiej przyjemności. (…) Straszne jest moje życie.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Ani drgnąłem i powiedziawszy parę cierpkich rzeczy i dawszy w mordę komu trzeba, opuściłem lokal.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Ach, Ty okrutna świntuko – żeby nic tyle czasu nie napisać, a ja Cię tak kocham, Ty cholerko obrzydłobuliwko.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "A co za ohydna menda jest ten Zahradnik. Podobno 22-letni onanista.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Bardzo Cię całuję i odpowiednio miętoszę, i miądlę, jak mogę.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Bardzo wygodne stanowisko nie rozumieć. Doszedłem 38 lat tą metodą.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Błagam Cię, zgódź się na mnie takiego, jakim jestem, i nie bierz na smycz. Drugiego nie znajdziesz takiego – to nie ma co.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Bóg, widząc, że narzekam, będąc zdrowym jak byk, dał mi nowego szpryca. Jest to początek chorób, które będą stanowić kres mego męczeńskiego żywota.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Całuję bardzo aż do kości.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Całuję Cię, moja biedna męczennico miłości. Czy uczucia erotyczne nie zaczynają się w Tobie budzić?", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Całuję Cię, Moja Najdroższa, i niech Cię ten dziwny stwór, do którego się modlisz 2 razy dziennie, natchnie czymś dobrym.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Całuję Cię w metafizyczny pępek.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Chce mi się spać i idę spać. Cóż jest lepszego nad sen?", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Ciągle męczy mnie wizja życia skończonego za życia bezsensownego i przepełnionego nie dającą się zabić męczarnią.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Ciskam Cię i łuję, i pobijam, i mdolę.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Czuję się tak jak po śmierci Jadwigi Janczewskiej. Żadnej nadziei. Szereg bezsensownych dni, śmierci za życia.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Czyż nie rozumiesz tych wymiarów, w których kontemplacja zwiędłej trawki na stokach Gubałówki zastąpi ci auto na Riwierze.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Dla Pani Dmochowskiej przesyłam ewentualnie serdeczne pozdrowienia (ale nie całowanie jakichś łap).", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Dziś cały dzień coś robię, ale b. mi się chce płakać. Już nic z niczego nie będzie. Okropne.B. mi bez Ciebie źle. Zajrzałem do pustego pokoju i mało się nie rozpłakałem.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Dziś mało (no metr np.) rano nie popełniłem samobójstwa.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Izoluję się coraz bardziej. Czeka mnie nędza, choroba i śmierć. Nic więcej.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Jaki Szejtan Cię opętał, żeby mnie tak męczyć. Kiedy ja czekam listu ze zgodą, Ty stajesz dęba na wszystkie kopyta.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Jestem idealnym mężem w porównaniu do innych. Ale w klatce zdechnę marnie. Taką mam naturę. (I bez klatki zdycham. A cóż dopiero?)", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Jestem w stanie zupełnego stężenia od środka, czuję się jak ryba w galarecie, z tym że cały świat jest galaretą.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Mam absolutną pewność, że życie moje jest skończone i że czekają mnie teraz tylko coraz gorsze męki. Lepiej byłoby teraz rozpić się i zakokainować, ale ze względu na Matkę nie mogę tego wykonać.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Muszę się odrodzić. Inaczej skończę samobójstwem albo bzikiem.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Może cię właśnie rżną i skrobią w tej chwili. Mój Boże – co bym dał, aby to widzieć!!!", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Nie mogę żyć z ludźmi. To bydło i idioci.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "O, czemu ludzie nie są zwierzętami – tak by było ładnie.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Okropnie tęsknię za przeszłym rokiem. Ach – żeby można nasze życie inaczej ułożyć. Znowu chce mi się płakać. Trzeba tytanicznej siły, aby to wytrzymać. A możliwości nieszczęść coraz większe. Pożary, choroby, wojny, śmierci, bóle itp. czyhają, a pociechy znikąd.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Podkochuję się w Tobie powoli, ale za to systematycznie.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Składam Ci na tym (a nie innym) miejscu serdeczne wyrazy współczucia i podziwu za wytrzymanie tych 3 lat ze mną.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "To wszystkiemu winne te dwa potwory z wiewiórką, oby im bogini Ptah przekręciła mózgi, aby nie mogły pisać sztuk.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Ty zdaje się myślisz, że jak dasz mi swobodę, to ja będę rżnął kurwy w Twoim łóżku. Mylisz się bardzo.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Walczę z krańcowym zniechęceniem do życia i powoli wysuwam się jak robaczek spod przywalającego mnie głazu.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Wczoraj czułem się strasznie. Ból, jakiego nie miałem dotąd w berzuchu, i sraczka wściekła. Dziś wstałem, ale nic nie jem. Techniczne trudności są, to nie ma rady, ale zgadzam się na nie i proszę Cię koniecznie, abyś nie robiła manigansów z człowiekiem chorym.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Wracając od Ireny Szarociny, spotkałem w polu tę małpę Domaniewską. Przeszła nie patrządz na mnie, czerwona jak kutas koci z uśmiechem robionym.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Wypiłem szklankę wódki i siedzę sam w moim pokoju. Chciałem pójść na spacer, ale boję się, że Matka byłaby się (byłaby się). Byłabysię (czy widziałaś kiedy byłabysie latające dookoła miejskich latarni w ciemną noc lipcową?). Nigdy i nigdy Ci tego nie życzę (rzyczę).", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Życie nie na szczytach czego-bądź jest nonsensem. Największy sens ma życie na szczycie nonsensu.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Ach, może ja was trochę do się zrażę, Jeśli wam powiem: wszyscyście gówniarze.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Babami (piętrząc takowe jedna nad drugą) zapychałem kompletną pustkę, która się teraz, przy pierwszej większej katastrofie, zdemaskowała. Jestem jak ryba na brzegu. Nie jestem artystą i trudno mi nim zostać – to jest najgorsze.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Brak swobody to jest dla mnie = bzik i śmierć.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Gdyby tak do mózgu czopki można było wpuszczać.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Kocham Cię strasznie, ale swoboda to wielka rzecz.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Krążą o mnie plotki wyssane z wielkiego palca czyjejś brudnej nogi.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Nineczko: Szalenie cię kocham i jestem w rozpaczy, że jeżdżę na nartach bez Ciebie. Co robić? Ale na myśl o braku swobody robi mi się zimno. Ciągle to samo. Czyż Ty, taka mondra, nie znajdziesz na to sposobu. Bo Blizbor był brutal i nie kochał żony, a ja nie i kocham Cię.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Pogardzam wszystkimi i mam wstręt taki do hołoty umysłowej, że rzygam.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Tak ciągle żałuję Ciebie, do cholery, dla siebie. Mieszkaj gdzie indziej, ale bądź.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Zaklinam Cię, nie rób tego głupstwa, aby psuć coś tak sztucznego i ślicznego jak nasze małżeństwo.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "A tak głupio się układa całe życie – tyle rzeczy ginie – tylu szkoda i wychodzi bolesny nonsens, a po drodze jak kupki gówienek nikomu niepotrzebne dziełka.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Byron umarł tak młodo I nic mu się nie stało – Czemuż bym nie miał i ja – Choć życia troszeczku mało.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Dziś czuję: 1) koniec życia, 2) zbliżającą się chorobę i śmierć, 3) jestem b. smutny i rozumiem dobrze L[udwika] XV, który na starość utopił się w rozpuście. Ja skończę w filozofii.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Jestem bardzo zgnębiony po orgii. Ale musiałem przez to przejść, aby zobaczyć, co jest na dnie. Mój stosunek do Ciebie jest niezmienny. Jesteś jedyną istotą na ziemi dla mnie. Ha – trudno – spróbujemy żyć dalej. Ty masz swoje cierpienia, ja swoje – może jakoś przetrwamy.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Kobra bardzo jest niedobra, Uch – jak kobra jest niedobra. Lecz czy to jest jej, ach, wina? Onaż działa jak maszyna. Człowiek jest, ach, taki też, Jeży się jako ten jeż. Każda baba jest niedobra Jako pierwsza lepsza kobra! Tak – lecz ona o tym wie, Co za świństwo, fuj, ach, fe!", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Wszyscy są nieszczęśliwi, że pracują w biurach, a drudzy są nieszczęśliwi, że nie pracują. A inni są nieszczęśliwi, bo nie wiedzą czy będą mieli za tydzień na obiad.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Mówi pan, że nie jestem patriotą? Nie byłem nim właściwie nigdy. Stłumiłem te uczucia, jak tylko zrozumiałem, że właściwie narodów już nie ma. Jest jedna wielka Hydra, tym straszniejsza, że jest maszyną. To jest szczęśliwa ludzkość.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Tajemnica osobowości – tylko łącząc się odnajdujemy to, co nas dzieli. Nieskończoność jest między nami i tylko dlatego jesteśmy nieskończenie bliscy.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Wyższością jednego człowieka nad drugim nie jest zdolność tworzenia rzeczywistości, tylko zdolność odpowiedniego teoretyzowania rzeczywistości już stworzonej.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Wstydzę się, że jestem człowiekiem. Ale w naszych czasach nastąpiła dysocjacja idei danego człowieka od jego wartości etycznej. Prorok może dziś być świnią – jest to przykre, ale to jest fakt. Zresztą na razie świnią nie jestem mimo całej nienawiści do ludzi – nienawidzę ludzi dzisiejszych.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Znowu mi się przypomniał mój mąż. Straszny to był wprost mezalians. I Bóg mnie za to pokarał. Bóg mezaliansów nie lubi.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Błogosławię was, moje dzieci. Życzę ci prędkiej i niespodziewanej śmierci, moja córuchno. Będziesz najpiękniejszym z aniołków, których wieniec oplata tron Wszechmogącego.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Tak – katolikiem to jesteś, mistrzu Pawle, ale nie chrześcijaninem. To wielka, to bardzo wielka różnica.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Ciągłe zaprzątanie umysłów młodzieży tylko tym, że Jasiek Wątorek skoczył o trzy cm wyżej niż Maciek Wąbała, jest objawem przykrym i mogącym na długich dystansach dać w wymiarze ogólnej kultury narodowej wyniki bardzo smutne.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Czemu większość ludzi, którzy bezwzględnie śmierdzieć nie powinni, jednak śmierdzi?", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Mycie codziennie całej skóry mydłem jest obowiązkiem każdego, który chce się za człowieka uważać.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Na długo przed wprowadzeniem tytoniu ludzie mordowali się niezgorzej. Może dopomagał im w tym alkohol – czort wie – nie moim zadaniem jest pisać historię narkotyków całego świata. Zresztą – kiedyś nie było też alkoholu.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Niech będą przeklęci Indianie i ci, którzy to świństwo do nas zawlekli.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Palacz (…) plugawe własne dowcipy bierze za najczystszy „esprit”, eksperymentalne spod ciemnej gwiazdy wymysły uważa za objawienia, a dupowate ględzenia za ostatni wybłysk „causeurstwa”. Wymagania jego maleją i szuka tylko kupy durniów, wśród których mógłby jeszcze brylować swoim zaćmionym mózgiem.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Są narody czyste i są brudne. Powiedzmy sobie otwarcie, że należymy do tych ostatnich, i starajmy się temu zaradzić. Czytając powieści polskie, rosyjskie lub francuskie, zawsze mam ten problem na myśli: czy aby ci wszyscy ludzie są dobrze wymyci.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Cóż to jest za, ach, ohyda — Ja mam syna schizoida! Czemuś nie jest ty pyknikiem, Tylko tym wymokłym smykiem?", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Nie ma na świecie istoty bardziej zakłamanej na temat swego stanowiska i znaczenia w czasoprzestrzennym kontinuum świata jak przeciętny Polak.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Przyjęcie chrześcijaństwa i w ogóle kultury z Zachodu, a nie od Bizancjum, było tym błędem inicjalnym, który zwichnął całą naszą historię i misję narodową. (…) Stąd ciągłe nasze szarpanie się w połowiczności między istotnym przeznaczeniem a skutkami pierwszego potknięcia się.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Ty moja, ach – ach, przeciem ja utracił ciebie, Ach, w tej miłości, ach, ja byłem, ach, jak w niebie, Rozstanie to zabija me uczucie tak, Że jestem teraz taki zwykły, smutny sobie flak itd., itd.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Bo cóż jest straszniejszego, jak ta godzina od drugiej do trzeciej popołudniu, kiedy nic ukryć przed sobą nie można i naga okropność metafizyczna przebija jak kieł zwaliska codziennych złud, którymi staramy się zabić bezsens życia bez wiary… O, Boże! – Zakrył pysk rękami i zastygł.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Bo sen przecie nigdy nie jest przeżywany bezpośrednio aktualnie w chwili swego śnienia się – istnieje tylko i jedynie jako wspomnienie.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Czy to jest prawdą o tobie, co sam sobie wyobrażasz, czy to, czym jesteś faktycznie w splotach, kłębiącej się według transcendentalnych, metafizycznych praw, społeczności.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Dobroć nie może wypływać ze słabości, tylko z potęgi.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Genezyp poczuł znowu jakieś tam męskie skomlenia i nakazy wewnątrz ciała. Gruczoły zaczynały się ruszać, niezależnie od stanów ducha. Co on je w ogóle obchodził – teraz użyjemy my, a resztę niech biorą sobie wszyscy diabli.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Ja lubię literaturę, bo dla mnie tam jest więcej życia niż w moim własnym. Jest ono tam w takiej kondensacji, w jakiej nie znajdę go w rzeczywistości nigdy.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Ja nie chcę znać społeczeństwa. Muszę żyć w tym błocie, ale też izoluję się od niego.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Jest się choćby w niekontrolowanych myślach swych takim, jakim się jest naprawdę, i nie trzeba żałować tej odrobiny swobody, jaką się ma w tym potwornym więzieniu, jakim jest świat i sam człowiek dla siebie.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Matki boją się zamawiać portrety swoich córek w mojej firmie, nawet dorośli mężczyźni siadają z niewyraźnymi minami „na aparat”, tak, jakby się spodziewali, że co najmniej, zamiast rysować, powyrywam im znienacka zęby lub wykłuję oczy ołówkiem.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Metafizyczny onanizm – innego na to słowa nie ma. Bo jest i maksymalna samotność (któż jest samotniejszy od onanisty?), i bezwstyd, i rozkosz, i ból, i dziwność zaziemska tego niezróżniczkowanego amalgamu bólu i rozkoszy, i niedościgłe piękno wbite jak kieł w ohydę bezmierną, ostateczną.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Mogę się zabić, ale na myśl, że mógłbym nie istnieć wcale, zimno mi się robi z przerażenia.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Na starość wymagania nasze rosną, a możliwości maleją.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Naucz się panować nad własną siłą. To trudniejsze jest od pokonania słabości – wierz mi.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Nic, psia-krew, nie działo się po prostu – wszystko było pokłębione, poplątane, skiełbaszone, jak naumyślnie przyprawiona przez złego ducha piekielna życiowa sałatka.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Nie posądzą mnie o to, że zostałem rozstrzelany przez komunistów, bo nie ma w Polsce Sowietów i ja niestety żyję i na razie piszę dalej.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Nieskończone są kondygnacje duszy ludzkiej – trzeba tylko umieć brnąć nieustraszenie w głąb – albo się zdobędzie swój własny szczyt, albo się zginie – w każdym razie nie będzie to psie życie miernot, wiedzących zaledwie to, że są i to nie bardzo.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Ostateczna prawda, że nic nie jest tym, czym być powinno…", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Prędzej czy później zwariować muszę, bo się nie w świecie, ale w sobie duszę.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Rozumiem właśnie twórczość nie jako produkowanie tej idiotycznej, nikomu niepotrzebnej tak zwanej „czystej formy” i nie jako odwalanie rzeczywistości, tylko jako stwarzanie rzeczywistości nowej, do której uciec można od tej, której mamy dosyć po same gardła…", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Stwarzać siłę, tej zawsze trzeba będzie, a cel równie zawsze się znajdzie – nie ten, to inny.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Tak – to jest pewne, że sam fakt istnienia jest potworny: polega na krzywdzie innych, począwszy od milionów istnień, ginących w nas w każdej chwili – i rodzących się – to prawda, ale na taką samą mękę, abyśmy my mogli trwać ten marny wycinek czasu.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Tym właśnie miałem być, raz na wieczność całą – takim właśnie albo wcale.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Wiecznie to samo balansowanie między śmiercią, jako jedynym nasyceniem, a życiem, rozproszkowanym w przypadkowości (to było najokropniejsze) nawet tych niby „koniecznych” „dzieł sztuki”.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Wielkość jest tylko w perwersji.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Wierzę w Boga, ale innego niż ten, który jest przedstawiony w dogmatach naszego Kościoła. Bóg jest wszystkim i nie rządzi światem, tylko samym sobą w sobie.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Wszystko, co było głębokim, powstało tylko z rozpaczy ostatecznej i zwątpienia.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Wszystko, co czynimy, nawet my, są to tylko różne formy tego zamaskowania przed sobą ostatecznego nonsensu istnienia.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Zresztą u niektórych samoanaliza staje się po prostu tylko samolizą – samolizaniem się wdzięcznego kotka.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Że też nic przyjemnego nie może dłużej trwać jak pięć do dziesięciu minut.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Życie jest jak rana – którą zapełnić można tylko rozkoszą.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Życie nic z literaturą wspólnego nie ma – chyba u autorów, którzy w ogóle do literatury nie należą – są bezmyślnymi fotografami jakichś zatęchłych kącików rzeczywistości.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Czyż naprawdę nie ma już ludzi na tym świecie? Czyż wszyscy stali się tylko kółkami zegara? Dajcie mi choć nakręcać ten zegar!", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Pragmatysta jest to zwykłe bydlę, z tą różnicą, że teoretyzując swoje bydlęctwo, wmawia to innym jako jedyną filozofię.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Ale czyż miłość to nie jest właśnie: dwoje zwierząt, które się pożądają do utraty zmysłów?", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Dane społeczeństwo jest o tyle dobre, o ile będąc członkiem tego społeczeństwa, nie odczuwa się właśnie tego, że się jest członkiem.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Wierzyliśmy w masonów, wierzyliśmy w Żydów, przez wielkie Ż. Teraz wierzymy w Nich. Nam potrzeba jakiejkolwiek wiary…", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "A czy Bóg, gdyby chciał, mógłby stworzyć drugiego Boga, takiego samego – przecież jest wszechmocny. Wtedyby się nie nudził.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "A jednak dobrze jest, wszystko jest dobrze. Co? – może nie? Dobrze jest, psiakrew, a kto powie, że nie, to go w mordę!", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Co by dał, aby móc być z czystym sumieniem homoseksualistą, artystą, kokainistą – w ogóle jakimś „istą”, wszystko jedno jakim – nawet sportsmenom zazdrościł manii sportowej. A był tylko skomplikowanym umetafizycznionym masochistą.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Różnorodność przeżyć nigdy nie zaszkodzi, Jeśli człek się przy tym nie bardzo zasmrodzi, A gdy i to nawet, i tak nic nie szkodzi, Bo właściwie mówiąc, kogo to obchodzi!", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Tfu, do czorta! Pękła mi aorta!", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Trzeba mieć duży takt, By skończyć trzeci akt. To nie złudzenie – to fakt.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "W srebrzyste pola chciałbym z Tobą iść I marzyć cicho o nieznanym bycie, W którym byś była moją samotnością, I w noc tę prześnić całe moje życie.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "A mama to była moja największa lalka. Tatuś z nią się też bawił jak z lalką – to była nasza wspólna lalka. Mama mówiła, że u nas w rodzinie wszystkie panienki w dwunastym roku przestają się bawić lalkami. Ja skończyłam dwanaście lat i mama umarła. Mamę zakopali grabarze, a ja zakopałam lalki.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Ja, panie Nibek, wolałbym nie żyć niż zobaczyć coś podobnego. Słońce świeci, ładna pogoda, a mnie się zdaje, że wszystko jest pokryte jakimś czarnym puchem. Na dwa kroki przede mną unosi się jakaś czarna ścierka. Och! Żebym mógł nie myśleć!", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Może zechcesz to mi nawet wmówić, że cię nie zastrzeliłem? Zabiłem cię, jak zborsuczoną sukę tym oto browningiem systemu Clement.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Nalej mi tymczasem kawy, mój Ignacy. I przestań się tak bać. Jeżeli jestem nawet widmem, to w każdym razie różnię się od innych. Jestem widmem, które je i pije. Nawet wódkę pije, mój biedny Ignacy.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Chodzi mi o to, aby na scenie, człowiek, lub jaki inny stwór popełnić mógł samobójstwo z powodu wylania się szklanki wody, ten sam stwór, który pięć minut temu tańczył z radości z powodu śmierci ukochanej matki.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Gówniarz Zakopanego.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Idź książeczko między ludzi, Idź i piękne myśli budź. A gdy myśl się piękna zbudzi, Sama zarżnie wszelką chuć.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Każda forma idealizmu poniżej solipsyzmu jest kompromisem jego z poglądem życiowym dla celów ubocznych i jako taka musi być bezwartościowa.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Każdy może tworzyć byle co i ma prawo być z tego zadowolonym, byle by nie był w swej pracy szczerym i znalazł kogoś, który równie kłamliwie będzie to podziwiał.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Klijent musi być zadowolony. Nieporozumienia wykluczone.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Ludzie dobrzy dla zwierząt bywają potworni w stosunku do bliźnich swoich.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Ludzie nie są znowu tak wielkim bydłem i bez idei żyć im trudno.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = " (…) nie dość jest istnieć po prostu, nierefleksyjnie, biernie, negatywnie, trzeba jeszcze istnienie swe zamanifestować wyraźniej, na tle możliwej śmierci i otaczającej nicości…", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Nie jest to przyjemność duża Cały dzień malować stróża I za taki marny zysk Zgłębiać taki głupi pysk.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Nie wiesz, co robisz, że palisz. Chcesz, to giń, psiakrew – palenie jest czymś okropnym, zwalającym z nóg byki.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Niebezpiecznie jest opierać wielkość swą na ujemnej wartości swych nieprzyjaciół.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Niedobrze jest bezkarnie prześcignąć samego siebie.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Och, czemuż nie jestem zwierzęciem W preriach lub w jakiej wodzie! Och! Któż mnie wreszcie nasyci W miłości potwornym głodzie.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Piekielne pomysły działają na zmysły a dusza gdzieś skryta nikt o nią nie pyta (…).", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Pojęcie (IP) implikuje pojęcie ograniczoności tego (IP). Pojęcie ograniczoności (IP) implikuje pojęcie jednej jedynej Formy Istnienia w całości, w której jako jej ograniczenia istnieją (IPN).", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Poza tym wszystko jest gównem – to znaczy wszystko poza filozofią. Bez niej byłbym zwykłym gówniarzem.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Religii nie ma (…) ginie jeszcze sztuka i filozofia i to ginie w nas. To są banały od których rzygać się zachciewa. Ale trzeba zrozumieć tych, którzy w obrębie odpowiadających im istotności i zjawisk muszą przeżyć swoje życie. To nie jest chwilami ani łatwe, ani zabawne.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Szalenie mi się chce dziewczynek, a na razie nie mam żadnej.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Teraz jestem od dwudziestu lat żonaty [sic!], bez dzieci na szczęście, gdyż odpowiedzialność za nie doprowadziłaby mnie do szaleństwa.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Tylko łącząc się, odnajdujemy to, co nas dzieli.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Uwolnijcie mnie od życia, a łaskę mi zrobicie.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "W danej chwili nawet nie chcę umierać ale i żyć nie mam wielkiej ochoty.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "W kobiecie interesują mnie tylko usta, nogi i środek. Piersi dla mnie mogą w ogóle nie istnieć.", Author = "Stanisław Ignacy Witkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Ignacy_Witkiewicz", Text = "Żadna, nawet największa miłość do kobiety pokonania tej samotności dać nie może. Z kobietą można się zniszczyć albo spospolicieć i zmarnieć, albo co najwyżej żyć tym normalnym życiem pracującego w społecznej maszynie automatu. Może najlepiej w łeb sobie palnąć od razu.", Author = "Stanisław Ignacy Witkiewicz" },
        };
    }
}